	/// <summary>
	/// Ports of the local CLI server (`beam server serve`). Each workspace prefers its own port, so the URL an AI
	/// agent is configured with stays the same from one run to the next, and so the Unity editor and the CLI pick the
	/// same one without talking to each other.
	/// </summary>
	public static class CliServerPorts
	{
