		public const int RANGE_START = 8342;

		/// <summary>The last port the CLI server may bind.</summary>
		public const int RANGE_END = RANGE_START + 3000;

		// Preferred ports start above the bundles management API (8360-8460) and stop short of RANGE_END,
		// leaving room to auto-increment when the preferred port is taken.
		private const int PREFERRED_START = 8500;
		private const int PREFERRED_SPAN = 2700;

		/// <summary>
		/// The port the server for <paramref name="workspaceDirectory"/> tries first. The path is compared
		/// case-insensitively with forward slashes and no trailing separator.
		/// </summary>
