			{
				uint hash = 2166136261;
				foreach (var b in Encoding.UTF8.GetBytes(normalized))
				{
					hash = (hash ^ b) * 16777619;
				}
				return PREFERRED_START + (int)(hash % PREFERRED_SPAN);
			}
		}
	}
